HTML = r'''<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>STELLA</title><style>
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;font-family:Arial,sans-serif}body{background:#f5f5f7;color:#111;height:100dvh;overflow:hidden}.hidden{display:none!important}button,input,select{font:inherit}button{cursor:pointer}#auth{height:100%;display:grid;place-items:center;padding:20px;background:#f5f5f7}.card{width:min(400px,100%);background:#fff;padding:30px;border-radius:24px;border:1px solid #ddd;box-shadow:0 12px 40px #0002;text-align:center}.card input{width:100%;padding:14px;margin:6px 0;border:1px solid #ccc;border-radius:12px}.card button{width:100%;padding:14px;margin-top:10px;border:0;border-radius:12px;background:#1677ff;color:#fff}.switch{margin-top:16px;color:#1677ff}.error{color:#c00;min-height:20px;margin-top:8px}#app{height:100%;display:flex;flex-direction:column}header{height:58px;flex:0 0 58px;background:#fff;border-bottom:1px solid #ddd;display:flex;align-items:center;padding:0 14px;gap:12px;position:relative;z-index:80}.hamb{border:0;background:transparent;font-size:25px;width:38px}.brand{font-weight:bold;font-size:21px;flex:1}.headuser{font-size:13px;color:#777}.logout{border:1px solid #ddd;background:#eee;border-radius:9px;padding:7px 10px}#workspace{display:flex;min-height:0;flex:1;position:relative}#side{width:285px;background:#fff;border-right:1px solid #ddd;display:flex;flex-direction:column;z-index:70}.sideTop{padding:14px;border-bottom:1px solid #ddd}.sideTitle{font-weight:bold;font-size:18px;margin-bottom:10px}.sideBtn{width:100%;text-align:left;border:1px solid #ddd;background:#f3f3f5;border-radius:11px;padding:11px;margin:4px 0}.sideSection{padding:12px 14px 6px;color:#555;font-size:12px;text-transform:uppercase}.history{overflow:auto;flex:1;padding:0 10px}.chatItem{width:100%;border:1px solid transparent;background:#fff;text-align:left;padding:11px;border-radius:10px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.newChat{margin:12px;border:0;background:#1677ff;color:#fff;border-radius:12px;padding:13px}#backdrop{position:fixed;inset:58px 0 0;background:#0005;z-index:65}.backdropOff{display:none}#main{min-width:0;flex:1;display:flex;flex-direction:column;min-height:0}#chat{flex:1;min-height:0;overflow:auto;padding:20px}.message-row{width:min(820px,100%);margin:12px auto}.message{padding:14px 17px;border-radius:18px;line-height:1.5;white-space:pre-wrap;border:1px solid #ddd}.user{background:#1677ff;color:#fff;border-color:#1677ff}.stella{background:#fff;box-shadow:0 2px 10px #0001}.copy-btn{display:block;margin:7px 0 0 auto;width:34px;height:30px;border:1px solid #333;background:#fff;border-radius:8px}.loading-row .copy-btn,.welcome-row .copy-btn{display:none}.image-message{max-width:820px;margin:12px auto;background:#fff;padding:10px;border-radius:18px;border:1px solid #ddd}.generated-image{width:100%;max-height:700px;object-fit:contain;border-radius:12px}.image-actions{display:flex;gap:8px;margin-top:8px}.image-actions a,.image-actions button{border:1px solid #ddd;background:#eee;border-radius:9px;padding:9px 12px;text-decoration:none}#inputArea{display:flex;flex-direction:column;gap:8px;padding:10px 14px;padding-bottom:calc(10px + env(safe-area-inset-bottom));background:#fff;border-top:1px solid #ddd}.composer{display:flex;gap:8px;align-items:center}.plus{height:46px;width:46px;flex:0 0 46px;border:1px solid #ddd;border-radius:14px;background:#eee;font-size:25px}.input{min-width:0;flex:1;padding:14px;border:1px solid #ccc;border-radius:15px;background:#fff;outline:0}.send{height:46px;border:0;border-radius:14px;background:#1677ff;color:#fff;padding:0 18px}.pending{width:100%;display:flex;gap:10px;overflow:auto}.pending-card{position:relative;flex:0 0 110px;height:90px;border:1px solid #ccc;border-radius:12px;background:#f3f3f5;padding:5px}.pending-card img,.pending-card video{width:100%;height:100%;object-fit:cover;border-radius:9px}.pending-card .remove{position:absolute;right:4px;top:4px;width:24px;height:24px;border:0;border-radius:50%;background:#000b;color:#fff}.quick{position:absolute;bottom:75px;left:12px;background:#fff;border:1px solid #ddd;border-radius:15px;padding:8px;box-shadow:0 8px 30px #0003;z-index:75;width:230px}.quick button{display:block;width:100%;border:0;background:#fff;text-align:left;padding:12px;border-radius:10px}.page{position:absolute;inset:0;background:#f5f5f7;z-index:60;padding:14px;overflow:auto}.panel{max-width:900px;margin:auto}.panelHead{display:flex;align-items:center;gap:12px;margin-bottom:15px;position:sticky;top:-14px;background:inherit;padding:10px 0;z-index:2}.back{border:1px solid #ddd;background:#fff;border-radius:10px;padding:9px 12px}.searchRow{display:flex;gap:8px;margin-bottom:14px}.searchRow input{flex:1;padding:11px;border:1px solid #ccc;border-radius:10px;background:#fff}.pluginCard,.detail,.setting,.updateCard{background:#fff;border:1px solid #ddd;border-radius:15px;padding:15px;margin:10px 0}.muted{color:#555;font-size:14px;line-height:1.45}.model{border:1px solid #ddd;border-radius:13px;padding:14px;margin:10px 0}.model button,.try{border:0;background:#1677ff;color:#fff;border-radius:10px;padding:10px 14px}.modelActions{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:12px}.setting{display:flex;justify-content:space-between;align-items:center}.galleryGrid{display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:12px}.tile{background:#fff;border:1px solid #ddd;border-radius:14px;padding:8px}.tile img,.tile video{width:100%;aspect-ratio:1;object-fit:cover;border-radius:10px}.tile small{display:block;padding:6px}.updateCard p{line-height:1.5}.updateCard ul{margin:8px 0 0 20px;padding:0}.updateCard li{margin:5px 0}.updateDate{font-size:12px;color:#666}.modal{position:fixed;inset:0;background:#0008;z-index:100;display:grid;place-items:center;padding:18px}.modalBox{width:min(760px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:20px;padding:20px}.modalHead{display:flex;justify-content:space-between;align-items:center}.close{border:1px solid #ddd;background:#fff;border-radius:9px;padding:7px 10px}.uploadOpts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.uploadOpts button{padding:18px 10px;background:#f3f3f5;border:1px solid #ddd;border-radius:13px}.pluginPick{display:grid;gap:10px}.pluginPick button{padding:14px;text-align:left;background:#fff;border:1px solid #ddd;border-radius:12px}.pluginPick strong{display:block}.pluginPick span{color:#555;font-size:13px}.dropHint{padding:14px;border:1px dashed #aaa;border-radius:12px;margin-top:12px}@media(max-width:720px){#side{position:fixed;top:58px;bottom:0;left:0;height:auto;transform:translateX(-102%);transition:transform .16s;box-shadow:8px 0 30px #0004}#side.open{transform:translateX(0)}.headuser{display:none}.page{padding:12px}.uploadOpts{grid-template-columns:1fr}.galleryGrid{grid-template-columns:repeat(2,minmax(0,1fr))}}body.dark,#auth.dark{background:#000;color:#fff}body.dark header,body.dark #side,body.dark #inputArea,body.dark .card,body.dark .page,body.dark .modalBox,body.dark .pluginCard,body.dark .detail,body.dark .setting,body.dark .updateCard,body.dark .model,body.dark .tile,body.dark .quick,body.dark .quick button{background:#000;color:#fff;border-color:#fff}body.dark .sideBtn,body.dark .back,body.dark .close,body.dark .uploadOpts button{background:#000;color:#fff;border-color:#fff}body.dark .chatItem{background:#000;color:#fff}body.dark .stella{background:#000;color:#fff;border-color:#fff;box-shadow:none}body.dark .input,body.dark .searchRow input,body.dark .card input{background:#000;color:#fff;border-color:#fff}.muted{color:#555}body.dark .muted,body.dark .updateDate{color:#fff}
</style></head><body>
<div id="auth"><div class="card"><h1>✦ STELLA</h1><p id="authSub">Create your account</p><input id="username" placeholder="Username"><input id="password" type="password" placeholder="Password"><button onclick="auth()" id="authBtn">Create account</button><div id="authErr" class="error"></div><div id="authSwitch" class="switch" onclick="toggleAuth()">Already have an account? Log in</div></div></div>
<div id="app" class="hidden"><header><button class="hamb" onclick="toggleSide()">☰</button><div class="brand">✦ STELLA</div><span class="headuser" id="welcome"></span><button class="logout" onclick="logout()">Log out</button></header><div id="workspace"><aside id="side"><div class="sideTop"><div class="sideTitle">STELLA</div><button class="sideBtn" onclick="openPage('memory');loadGallery()">▦ Memory</button><button class="sideBtn" onclick="openPage('plugins');renderPluginLibrary()">＋ Plugins</button><button class="sideBtn" onclick="openPage('updates');renderUpdates()">▣ Update Log</button><button class="sideBtn" onclick="openPage('settings');loadSettings()">⚙ Settings</button></div><div class="sideSection">Previous chats</div><div id="history" class="history"></div><button class="newChat" onclick="newChat()">＋ New chat</button></aside><div id="backdrop" class="backdropOff" onclick="closeSide()"></div><main id="main"><div id="chat"></div><div id="inputArea"><div id="pending" class="pending hidden"></div><div class="composer"><button class="plus" onclick="openQuick(event)">＋</button><input id="message" class="input" placeholder="Message STELLA..." autocomplete="off"><button class="send" onclick="sendMessage()">Send</button></div><div id="quick" class="quick hidden"><button onclick="openUpload()">Upload</button><button onclick="openPluginChooser()">Plugins</button></div></div></main></div>
<section id="memory" class="page hidden"><div class="panel"><div class="panelHead"><button class="back" onclick="closePages()">Back</button><h2>Memory</h2></div><div class="searchRow"><input id="memorySearch" placeholder="Search images and videos..." oninput="filterGallery()"></div><div id="galleryGrid" class="galleryGrid"></div></div></section><section id="plugins" class="page hidden"><div class="panel"><div class="panelHead"><button class="back" onclick="closePages()">Back</button><h2>Plugins</h2></div><div class="searchRow"><input id="pluginSearch" placeholder="Search plugins..." oninput="filterLibrary()"></div><div id="pluginLibrary"></div></div></section><section id="updates" class="page hidden"><div class="panel"><div class="panelHead"><button class="back" onclick="closePages()">Back</button><h2>Update Log</h2></div><div class="searchRow"><input id="updateSearch" placeholder="Search updates..." oninput="renderUpdates()"></div><div id="updateList"></div></div></section><section id="settings" class="page hidden"><div class="panel"><div class="panelHead"><button class="back" onclick="closePages()">Back</button><h2>Settings</h2></div><div class="setting"><span>Theme</span><select id="theme" onchange="saveSettings()"><option value="system">According to device</option><option value="light">Light</option><option value="dark">Dark</option></select></div><div class="setting"><span>Memory across new chats</span><input id="memoryToggle" type="checkbox" onchange="saveSettings()"></div></div></section><div id="modal" class="modal hidden" onclick="if(event.target===this)closeModal()"><div class="modalBox"><div class="modalHead"><h2 id="modalTitle"></h2><button class="close" onclick="closeModal()">Close</button></div><div id="modalBody"></div></div></div><section id="call" class="hidden"></section></div>
<script>
let loginMode=false,conversationId=localStorage.getItem('stella_conversation_id'),galleryItems=[],plugins=%s,pendingAttachments=[];const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const UPDATE_LOG=[{v:'v3.2.6',n:'UI, memory and attachment patch',p:['Update Log keeps past updates and has search.','Mobile menu layers no longer cover the controls.','Attachments stay with the same outgoing message.','Uploaded images and videos are saved to Memory.','Chat names use the conversation topic.']},{v:'v3.2.0',n:'Plugin and attachment foundation',p:['Added plugin library and model details.','Added image, voice and future video entries.']},{v:'v3.1.0',n:'STELLA service split',p:['Separated configuration, AI, voice and server responsibilities.']}];
function toggleAuth(){loginMode=!loginMode;$('authSub').textContent=loginMode?'Log in to your account':'Create your account';$('authBtn').textContent=loginMode?'Log in':'Create account';$('authSwitch').textContent=loginMode?'Need an account? Create one':'Already have an account? Log in'}async function auth(){let u=$('username').value.trim(),p=$('password').value;if(!u||!p){$('authErr').textContent='Username and password are required.';return}let r=await fetch(loginMode?'/login':'/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:u,password:p})}),d=await r.json();if(!r.ok){$('authErr').textContent=d.error||'Unable to continue.';return}show(d.username||u)}async function check(){let r=await fetch('/me'),d=await r.json();if(d.logged_in)show(d.username)}async function show(u){$('auth').classList.add('hidden');$('app').classList.remove('hidden');$('welcome').textContent=u;await loadSettings();await loadHistory()}async function logout(){await fetch('/logout',{method:'POST'});localStorage.removeItem('stella_conversation_id');location.reload()}
function closeSide(){$('side').classList.remove('open');$('backdrop').classList.add('backdropOff')}function toggleSide(){$('side').classList.toggle('open');$('backdrop').classList.toggle('backdropOff')}function closeQuick(){$('quick').classList.add('hidden')}function openQuick(e){e.stopPropagation();$('quick').classList.toggle('hidden')}document.addEventListener('click',e=>{if(!$('quick').contains(e.target)&&!e.target.classList.contains('plus'))closeQuick()});function closePages(){document.querySelectorAll('.page').forEach(x=>x.classList.add('hidden'));closeQuick();closeSide()}function openPage(id){closeQuick();closeSide();document.querySelectorAll('.page').forEach(x=>x.classList.add('hidden'));$(id).classList.remove('hidden')}
function openUpload(){closeQuick();$('modalTitle').textContent='Upload';$('modalBody').innerHTML='<div class="uploadOpts"><button onclick="pickFile(\'image/*\',\'image\')">Upload image</button><button onclick="pickFile(\'video/*\',\'video\')">Upload video</button><button onclick="pickFile(\'*/*\',\'file\')">Upload file</button></div><div class="dropHint">Choose a file. It stays above the message box until you tap Send.</div>';$('modal').classList.remove('hidden')}function pickFile(accept,type){let i=document.createElement('input');i.type='file';i.accept=accept;i.onchange=()=>i.files[0]&&stageFile(i.files[0],type);i.click()}async function stageFile(file,type){let b=await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)});pendingAttachments.push({type,name:file.name,data:b});closeModal();renderPending()}function renderPending(){let p=$('pending');if(!pendingAttachments.length){p.classList.add('hidden');p.innerHTML='';return}p.classList.remove('hidden');p.innerHTML=pendingAttachments.map((a,i)=>'<div class="pending-card">'+(a.type==='image'?'<img src="'+a.data+'">':a.type==='video'?'<video muted src="'+a.data+'"></video>':'<div>'+esc(a.name)+'</div>')+'<button class="remove" onclick="removePending('+i+')">×</button></div>').join('')}function removePending(i){pendingAttachments.splice(i,1);renderPending()}
function openPluginChooser(){closeQuick();$('modalTitle').textContent='Choose a plugin';$('modalBody').innerHTML='<div class="pluginPick">'+plugins.map(p=>'<button onclick="pluginModels(\''+p.id+'\')"><strong>'+esc(p.name)+'</strong><span>'+esc(p.description)+'</span></button>').join('')+'</div>';$('modal').classList.remove('hidden')}function pluginModels(id){let p=plugins.find(x=>x.id===id);$('modalTitle').textContent=p.name;$('modalBody').innerHTML='<div id="modalModels">'+(p.models.length?p.models.map(m=>'<div class="model"><strong>'+esc(m.name)+'</strong><p class="muted">Provider: '+esc(m.provider)+'<br>Good at: '+esc(m.good)+'<br>Setup: '+esc(m.setup)+'</p><button onclick="activate(\''+id+'\')">Use in this chat</button></div>').join(''):'<div class="detail">No model is configured yet.</div>')+'</div>'}function activate(id){closeModal();if(id==='image')imagePicker();else add('This plugin is prepared but no provider is configured yet.','stella')}
function closeModal(){$('modal').classList.add('hidden')}function renderPluginLibrary(){let q=($('pluginSearch').value||'').toLowerCase();$('pluginLibrary').innerHTML=plugins.filter(p=>(p.name+' '+p.description).toLowerCase().includes(q)).map(p=>'<div class="pluginCard"><strong>'+esc(p.name)+'</strong><p class="muted">'+esc(p.description)+'</p><p class="muted">Models: '+(p.models.length?p.models.map(m=>esc(m.name)).join(', '):'Not configured')+'</p><button class="try" onclick="activate(\''+p.id+'\')">Try it out in current chat</button></div>').join('')||'<div class="detail">No plugins found.</div>'}function filterLibrary(){renderPluginLibrary()}
function renderUpdates(){let q=($('updateSearch').value||'').toLowerCase();$('updateList').innerHTML=UPDATE_LOG.filter(x=>(x.v+' '+x.n+' '+x.p.join(' ')).toLowerCase().includes(q)).map(x=>'<div class="updateCard"><div class="updateDate">STELLA '+x.v+' - '+esc(x.n)+'</div><strong>'+esc(x.n)+'</strong><ul>'+x.p.map(y=>'<li>'+esc(y)+'</li>').join('')+'</ul></div>').join('')||'<div class="detail">No updates found.</div>'}
async function loadHistory(){let r=await fetch('/conversations');if(!r.ok)return;let d=await r.json();$('history').innerHTML='';d.conversations.forEach(c=>{let b=document.createElement('button');b.className='chatItem';b.textContent=c.title||'New chat';b.onclick=()=>loadConversation(c.id);$('history').appendChild(b)});if(conversationId&&d.conversations.some(c=>String(c.id)===String(conversationId)))loadConversation(conversationId);else if(d.conversations.length)loadConversation(d.conversations[0].id);else renderWelcome()}async function loadConversation(id){let r=await fetch('/conversation?id='+id);if(!r.ok)return;let d=await r.json();conversationId=String(id);localStorage.setItem('stella_conversation_id',conversationId);$('chat').innerHTML='';d.messages.forEach(renderStored);if(!d.messages.length)renderWelcome(false);scroll();closeSide()}function renderWelcome(){add("Hey! I'm STELLA.\nWhat are we doing today?",'stella')}function renderStored(m){if(m.attachment){renderAttachment(m.attachment,false);if(m.parts?.[0]?.text)add(m.parts[0].text,'user',false);return}let t=m.parts?.[0]?.text||'';if(m.role==='image'){try{let d=JSON.parse(t);showImage(d.url,d.prompt||'STELLA image',false)}catch(e){}return}add(t,m.role==='user'?'user':'stella',false)}function renderAttachment(a,doScroll=true){let row=document.createElement('div');row.className='message-row user-row';let box=document.createElement('div');box.className='message user';box.textContent=a.name||'Attachment';if(a.type==='image'){let im=document.createElement('img');im.src=a.data;im.style.maxWidth='100%';im.style.maxHeight='360px';im.style.display='block';im.style.marginTop='8px';box.appendChild(im)}else if(a.type==='video'){let v=document.createElement('video');v.controls=true;v.src=a.data;v.style.maxWidth='100%';v.style.maxHeight='360px';v.style.display='block';v.style.marginTop='8px';box.appendChild(v)}row.appendChild(box);$('chat').appendChild(row);if(doScroll)scroll()}
function newChat(){conversationId=null;localStorage.removeItem('stella_conversation_id');pendingAttachments=[];renderPending();closePages();$('chat').innerHTML='';renderWelcome();$('message').focus()}function add(t,type,doScroll=true){let row=document.createElement('div');row.className='message-row';let m=document.createElement('div');m.className='message '+type;m.textContent=t;row.appendChild(m);if(type==='stella'&&t&&!/^Thinking/.test(t)){let c=document.createElement('button');c.className='copy-btn';c.textContent='⧉';c.onclick=async()=>{await navigator.clipboard.writeText(t);c.textContent='✓'};row.appendChild(c)}$('chat').appendChild(row);if(doScroll)scroll();return m}function scroll(){$('chat').scrollTop=$('chat').scrollHeight}
function imagePicker(){closeQuick();$('modalTitle').textContent='Image generation';$('modalBody').innerHTML='<div class="searchRow"><input id="imagePrompt" placeholder="Describe the image..."></div><button class="try" onclick="generateImage($(\'imagePrompt\').value)">Generate</button>';$('modal').classList.remove('hidden')}async function generateImage(p){if(!p.trim())return;closeModal();add('Create an image of '+p,'user');let w=add('Generating an image of: '+p,'stella');let r=await fetch('/generate-image',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:p,conversation_id:conversationId})}),d=await r.json();if(!r.ok){w.textContent=d.error||'Image generation failed.';return}w.parentElement.remove();conversationId=String(d.conversation_id);localStorage.setItem('stella_conversation_id',conversationId);showImage(d.image_url,p,true);loadHistory()}function showImage(url,p,doScroll=true){let w=document.createElement('div');w.className='image-message';w.innerHTML='<img class="generated-image"><div class="image-actions"><a target="_blank">Download</a><button>Continue chatting</button></div>';w.querySelector('img').src=url;w.querySelector('a').href=url;w.querySelector('a').download='stella-image.png';w.querySelector('button').onclick=()=>$('message').focus();$('chat').appendChild(w);if(doScroll)scroll()}
async function sendMessage(){let text=$('message').value.trim();if(!text&&!pendingAttachments.length)return;let a=pendingAttachments.slice();pendingAttachments=[];renderPending();add(text||'Attached media','user');$('message').value='';let w=add('Thinking...','stella');let r=await fetch('/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,conversation_id:conversationId,attachments:a})}),d=await r.json();if(!r.ok){w.textContent=d.reply||d.error||'Something went wrong.';return}conversationId=String(d.conversation_id);localStorage.setItem('stella_conversation_id',conversationId);w.textContent=d.reply;loadHistory();scroll()}
function addCopy(m){}async function loadSettings(){let r=await fetch('/settings'),d=await r.json();if(!r.ok)return;$('theme').value=d.theme;$('memoryToggle').checked=d.memory_enabled;applyTheme(d.theme)}async function saveSettings(){let d={theme:$('theme').value,memory_enabled:$('memoryToggle').checked};await fetch('/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)});applyTheme(d.theme)}function applyTheme(t){let dark=t==='dark'||(t==='system'&&matchMedia('(prefers-color-scheme: dark)').matches);document.body.classList.toggle('dark',dark);$('auth').classList.toggle('dark',dark)}async function loadGallery(){let r=await fetch('/memory/gallery'),d=await r.json();galleryItems=d.items||[];renderGallery(galleryItems)}function renderGallery(a){$('galleryGrid').innerHTML=a.map(x=>'<div class="tile">'+(x.type==='video'?'<video controls src="'+x.url+'"></video>':'<img src="'+x.url+'">')+'<small>'+esc(x.name||x.prompt||'STELLA media')+'</small></div>').join('')||'<div class="detail">No saved images or videos yet.</div>'}function filterGallery(){let q=$('memorySearch').value.toLowerCase();renderGallery(galleryItems.filter(x=>(x.name||x.prompt||'').toLowerCase().includes(q)))}
$('message').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();sendMessage()}});$('password').addEventListener('keydown',e=>{if(e.key==='Enter')auth()});check();
</script></body></html>''' % json.dumps(PLUGINS,separators=(',',':'))
